import string

def encode_shift(s: str) -> str:
    """
    Returns encoded string by shifting every letter by 5 positions forward in the alphabet.
    Non-alphabetic characters are left unchanged.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift within alphabet, wrap around using modulo 26
            new_ord = (ord(ch) - ord('a') + 5) % 26 + ord('a')
            result.append(chr(new_ord))
        else:
            result.append(ch)
    return "".join(result)

def decode_shift(s: str) -> str:
    """
    Takes a string encoded with encode_shift and returns the decoded original string.
    """
    result = []
    for ch in s:
        if 'a' <= ch <= 'z':
            # Shift back by 5 to reverse the encoding
            new_ord = (ord(ch) - ord('a') - 5) % 26 + ord('a')
            result.append(chr(new_ord))
        else:
            result.append(ch)
    return "".join(result)
```

**Note:**  
My original implementation assumed only lowercase English letters and used a list comprehension with `chr((ord(ch)+5 - ord('a')) % 26 + ord('a'))`, which implicitly assumes all letters are lowercase and excludes non-letters. However, that approach could throw an error for non-letters (e.g., if `(ord(ch)+5 - ord('a'))` is negative for letters near 'z'). The improved version here explicitly checks that `ch` is a lowercase letter before shifting, and leaves non-letters unchanged, making the function safer and more robust for all input characters.

