import math

def words_in_sentence(sentence: str) -> str:
    """
    Returns a string consisting of words from the input sentence whose lengths are prime numbers,
    preserving the original order. Words of non-prime length are excluded.
    """
    def is_prime(n: int) -> bool:
        if n <= 1:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        for i in range(3, int(math.isqrt(n)) + 1, 2):
            if n % i == 0:
                return False
        return True

    words = sentence.split()
    filtered_words = [w for w in words if is_prime(len(w))]
    return " ".join(filtered_words)
